// generated by build.mjs from calc.mjs
function solar(ms, lat, lon) {
  const rad = Math.PI / 180;
  const d = ms / 86400000 + 2440587.5 - 2451545.0;
  const g = ((357.529 + 0.98560028 * d) % 360) * rad;
  const q = (280.459 + 0.98564736 * d) % 360;
  const L = (q + 1.915 * Math.sin(g) + 0.02 * Math.sin(2 * g)) * rad;
  const e = (23.439 - 0.00000036 * d) * rad;
  const ra = Math.atan2(Math.cos(e) * Math.sin(L), Math.cos(L));
  const dec = Math.asin(Math.sin(e) * Math.sin(L));
  const gmst = (18.697374558 + 24.06570982441908 * d) % 24;
  const H = ((gmst * 15 + lon) * rad) - ra;
  const la = lat * rad;
  const alt = Math.asin(Math.sin(la) * Math.sin(dec) + Math.cos(la) * Math.cos(dec) * Math.cos(H));
  let az = Math.atan2(-Math.sin(H), Math.tan(dec) * Math.cos(la) - Math.sin(la) * Math.cos(H)) / rad;
  az = (az + 360) % 360;
  return { alt: alt / rad, az };
}

function ukOffset(dateStr) {
  const [y, m, dd] = dateStr.split('-').map(Number);
  const lastSun = (mo) => { const t = new Date(Date.UTC(y, mo, 0)); return t.getUTCDate() - t.getUTCDay(); };
  const start = Date.UTC(y, 2, lastSun(3));
  const end = Date.UTC(y, 9, lastSun(10));
  const t = Date.UTC(y, m - 1, dd);
  return t >= start && t < end ? 1 : 0;
}

function lit(wall, ms, lat, lon) {
  const s = solar(ms, lat, lon);
  let diff = Math.abs(s.az - wall.face) % 360;
  if (diff > 180) diff = 360 - diff;
  return s.alt > wall.horizon && diff < 85;
}

function sunStrip(wall, dateStr, lat, lon) {
  const [y, m, d] = dateStr.split('-').map(Number);
  const off = ukOffset(dateStr);
  const out = [];
  let open = null;
  for (let min = 300; min <= 1260; min += 5) {
    const ms = Date.UTC(y, m - 1, d, 0, min) - off * 3600000;
    const on = lit(wall, ms, lat, lon);
    if (on && open === null) open = min;
    if (!on && open !== null) { out.push([open, min]); open = null; }
  }
  if (open !== null) out.push([open, 1260]);
  return out;
}

function dryHours(wall, rain) {
  let h = wall.dry * (2 + 0.6 * rain);
  if (wall.seeps && rain >= 10) h += 72;
  return Math.round(h * 10) / 10;
}

function ropeMax(rope, margin) {
  return (rope - margin) / 2;
}

const hhmm = (min) => {
  const h = Math.floor(min / 60), m = Math.round(min % 60);
  return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
};
window.WLC = { solar, ukOffset, lit, sunStrip, dryHours, ropeMax, hhmm };
